INSERT INTO sheets (slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES ('jq', 'jq Cheatsheet', 'Command-line JSON processor', NULL, 'Fast and flexible command-line JSON processor for querying, filtering, slicing, mapping, and transforming structured data.', NULL, 'https://jqlang.org/manual/', '[{"label": "jqlang.org/manual", "url": "https://jqlang.org/manual/"}]'::jsonb, '{}'::jsonb, ARRAY['jq', 'jqlang']::text[], '[{"icon": "💻", "title": "Invocation & Output Formatting", "tip": "Options controlling indentation, colorization, compacting, and raw text output from jq.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Output Formatting Options", "kind": "table", "copy_lines": false}]}, {"icon": "📥", "title": "Input Modes & Execution", "tip": "Options controlling how input data is ingested, parsed, and how exit codes are handled.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Input Processing Options", "kind": "table", "copy_lines": false}, {"label": "CLI Flags & Exit Behavior", "kind": "table", "copy_lines": false}]}, {"icon": "🏷️", "title": "Variables & CLI Arguments", "tip": "Pass dynamic parameters from shell environments or files into jq expressions.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Passing Arguments from CLI", "kind": "table", "copy_lines": false}, {"label": "Special Variable Bindings", "kind": "table", "copy_lines": false}]}, {"icon": "🔍", "title": "Basic Filters & Slicing", "tip": "Access fields, index arrays, slice sequences, and traverse hierarchies.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Identity & Field Access", "kind": "table", "copy_lines": false}, {"label": "Array Slicing & Iteration", "kind": "table", "copy_lines": false}]}, {"icon": "🏗️", "title": "Types, Construction & Formats", "tip": "Construct objects and arrays, interpolate strings, and encode or decode formats.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Value Construction & Interpolation", "kind": "table", "copy_lines": false}, {"label": "Format Strings & Decoders", "kind": "table", "copy_lines": false}]}, {"icon": "🧮", "title": "Operators & Logic", "tip": "Arithmetic, string repetition, deep merging, comparisons, and alternative operators.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Arithmetic & Concatenation", "kind": "table", "copy_lines": false}, {"label": "Comparisons & Boolean Logic", "kind": "table", "copy_lines": false}]}, {"icon": "🔀", "title": "Conditionals & Control Flow", "tip": "Control branching, error handling, generator limits, and loop iterations.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Branching & Error Handling", "kind": "table", "copy_lines": false}, {"label": "Generators, Limits & Loops", "kind": "table", "copy_lines": false}]}, {"icon": "📊", "title": "Arrays & Collections", "tip": "Iterate, filter, sort, aggregate, search, and reshape arrays.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Transformations & Aggregation", "kind": "table", "copy_lines": false}, {"label": "Sorting, Grouping & Searching", "kind": "table", "copy_lines": false}]}, {"icon": "🗂️", "title": "Objects & Key Inspection", "tip": "Inspect object keys, check membership, convert key-value entries, and pick fields.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Object Inspection & Membership", "kind": "table", "copy_lines": false}, {"label": "Entries & Field Selection", "kind": "table", "copy_lines": false}]}, {"icon": "📍", "title": "Paths, Tree Traversal & Updates", "tip": "Locate deep nodes with path arrays, prune keys, and perform surgical in-place updates.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Path Inspection & Modification", "kind": "table", "copy_lines": false}, {"label": "In-place Updates & Assignments", "kind": "table", "copy_lines": false}]}, {"icon": "🔤", "title": "Strings & Regular Expressions", "tip": "String splitting, joining, case conversion, trimming, and regex matching.", "layout": "grid", "body_cols": 1, "sections": [{"label": "String Utilities & Trimming", "kind": "table", "copy_lines": false}, {"label": "Regex Matching & Replacement", "kind": "table", "copy_lines": false}]}, {"icon": "📐", "title": "Math, Numbers & Type Checks", "tip": "JSON type introspection, numeric casting, rounding, and math constants.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Type Checks & Conversions", "kind": "table", "copy_lines": false}, {"label": "Math Functions & Constants", "kind": "table", "copy_lines": false}]}, {"icon": "⏱️", "title": "Dates & Timestamps", "tip": "Unix timestamps, ISO 8601 formatting, broken-down time arrays, and strftime.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Date Formatting & Parsing", "kind": "table", "copy_lines": false}]}, {"icon": "⚙️", "title": "Advanced Streams & SQL-style Queries", "tip": "Variable scopes, reduce/foreach accumulators, SQL-like indexing and joining, stream tuples.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Scoping, Reduction & Functions", "kind": "table", "copy_lines": false}, {"label": "Advanced I/O, Debugging & SQL-style", "kind": "table", "copy_lines": false}]}, {"icon": "📦", "title": "Modules & Function Definitions", "tip": "Define modular functions, organize libraries, and inspect runtime reflection metadata.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Custom Functions & Scopes", "kind": "table", "copy_lines": false}, {"label": "Module Imports & Libraries", "kind": "table", "copy_lines": false}]}, {"icon": "🍳", "title": "Practical Recipes", "tip": "Production-ready CLI one-liners for common day-to-day data manipulation tasks.", "layout": "wide", "body_cols": 1, "sections": [{"label": "CLI One-Liners & Piping", "kind": "table", "copy_lines": false}, {"label": "Data Transformation Recipes", "kind": "table", "copy_lines": false}]}]'::jsonb);
